WITH scored AS (SELECT id, order_id, method, amount, status, MIN(amount) OVER w_grp AS last4_min_amount, COUNT(amount) OVER w_grp AS last4_count_amount, MAX(amount) OVER w_grp AS last4_max_amount, PERCENT_RANK() OVER w_running AS amount_percent_rank FROM payments WHERE status NOT IN ('REFUNDED', 'SUCCESS') WINDOW w_grp AS (PARTITION BY method, status ORDER BY paid_at, id ROWS BETWEEN 3 PRECEDING AND CURRENT ROW), w_running AS (ORDER BY amount NULLS LAST)) SELECT id, method, status, last4_min_amount, last4_count_amount, last4_max_amount, CASE WHEN status RLIKE '^(SUCCESS|FAILED)$' THEN 'CORE' ELSE 'PRIORITY' END AS status_zone FROM scored ORDER BY method NULLS FIRST;
